import fs from 'fs';
import path from 'path';

import {
  DEFAULT_METRICS,
  exactMatchMetric,
  lengthVarianceMetric,
  toxicityMetric
} from './metrics.js';
import { resolveReportPath, toJson, toMarkdown } from './reporters.js';

const defaultFs = fs;

const ensureArray = (value) => (Array.isArray(value) ? value : []);

export function parseThresholds(thresholdStrings = []) {
  const result = {};
  const strs = Array.isArray(thresholdStrings) ? thresholdStrings : [thresholdStrings].filter(Boolean);

  for (const str of strs) {
    const match = String(str).match(/^([a-z_]+)=([0-9.]+)$/);
    if (!match) {
      throw new Error(`Malformed threshold: "${str}" (expected format: metric=value, e.g., exact_match=0.9)`);
    }
    const [, metricId, minStr] = match;
    const min = parseFloat(minStr);
    if (Number.isNaN(min) || min < 0 || min > 1) {
      throw new Error(`Invalid threshold value: ${minStr} (must be a number between 0 and 1)`);
    }
    result[metricId] = min;
  }
  return result;
}

export function evaluateThresholds(metrics = [], thresholds = {}) {
  const metricIds = new Set(metrics.map((m) => m.id));
  const thresholdList = [];

  for (const [metricId, min] of Object.entries(thresholds)) {
    if (!metricIds.has(metricId)) {
      const validIds = Array.from(metricIds).sort();
      throw new Error(
        `Unknown metric: "${metricId}" (valid: ${validIds.join(', ')})`
      );
    }

    const metric = metrics.find((m) => m.id === metricId);
    const score = metric.score;
    const passed = score !== null && score >= min;

    thresholdList.push({
      metric: metricId,
      min,
      score,
      passed
    });
  }

  return thresholdList;
}

export function loadDataset({ outputsPath, referencesPath, fs: fsModule = defaultFs } = {}) {
  if (!outputsPath) {
    throw new Error('outputsPath is required for evaluation.');
  }

  const outputsAbsolute = path.resolve(outputsPath);
  const outputsRaw = fsModule.readFileSync(outputsAbsolute, 'utf8');
  const outputs = JSON.parse(outputsRaw);

  let references = [];
  let referencesAbsolute = null;
  if (referencesPath) {
    referencesAbsolute = path.resolve(referencesPath);
    const referencesRaw = fsModule.readFileSync(referencesAbsolute, 'utf8');
    references = JSON.parse(referencesRaw);
  }

  return {
    outputs,
    references,
    outputsPath: outputsAbsolute,
    referencesPath: referencesAbsolute
  };
}

export function runEvaluations({
  outputs,
  references,
  metrics = DEFAULT_METRICS
} = {}) {
  const outs = ensureArray(outputs);
  const refs = ensureArray(references);

  const evaluations = metrics.map((metric) => {
    if (typeof metric === 'function') {
      return metric(outs, refs);
    }
    if (metric && typeof metric.evaluate === 'function') {
      return metric.evaluate(outs, refs);
    }
    throw new Error('Invalid metric supplied to runEvaluations.');
  });

  return evaluations;
}

export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  generatedAt = new Date().toISOString(),
  thresholds = {}
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const thresholdList = evaluateThresholds(evaluations, thresholds);
  const passed = thresholdList.length === 0 || thresholdList.every((t) => t.passed);

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  if (thresholdList.length > 0) {
    report.passed = passed;
    report.thresholds = thresholdList;
  }

  return report;
}

export function writeReport({
  report,
  format = 'json',
  reportPath,
  fs: fsModule = defaultFs
}) {
  const resolved = resolveReportPath(reportPath, format);
  const payload = format === 'markdown' ? toMarkdown(report) : toJson(report);
  fsModule.writeFileSync(resolved, payload, 'utf8');
  return resolved;
}

export {
  DEFAULT_METRICS,
  exactMatchMetric,
  toxicityMetric,
  lengthVarianceMetric
};

export default {
  loadDataset,
  runEvaluations,
  generateReport,
  writeReport,
  DEFAULT_METRICS,
  exactMatchMetric,
  toxicityMetric,
  lengthVarianceMetric
};

