4	import {
5	  DEFAULT_METRICS,
6	  exactMatchMetric,
7	  lengthVarianceMetric,
8	  toxicityMetric
9	} from './metrics.js';
10	import { resolveReportPath, toJson, toMarkdown } from './reporters.js';
11	
12	const defaultFs = fs;
13	
14	const ensureArray = (value) => (Array.isArray(value) ? value : []);
15	
16	export function parseThresholds(thresholdStrings = []) {
17	  const result = {};
18	  const strs = Array.isArray(thresholdStrings) ? thresholdStrings : [thresholdStrings].filter(Boolean);
19	
20	  for (const str of strs) {
21	    const match = String(str).match(/^([a-z_]+)=([0-9.]+)$/);
22	    if (!match) {
23	      throw new Error(`Malformed threshold: "${str}" (expected format: metric=value, e.g., exact_match=0.9)`);
24	    }
25	    const [, metricId, minStr] = match;
26	    const min = parseFloat(minStr);
27	    if (Number.isNaN(min) || min < 0 || min > 1) {
28	      throw new Error(`Invalid threshold value: ${minStr} (must be a number between 0 and 1)`);
29	    }
30	    result[metricId] = min;
31	  }
32	  return result;
33	}
34	
35	export function evaluateThresholds(metrics = [], thresholds = {}) {
36	  const metricIds = new Set(metrics.map((m) => m.id));
37	  const thresholdList = [];
38	
39	  for (const [metricId, min] of Object.entries(thresholds)) {
40	    if (!metricIds.has(metricId)) {
41	      const validIds = Array.from(metricIds).sort();
42	      throw new Error(
43	        `Unknown metric: "${metricId}" (valid: ${validIds.join(', ')})`
44	      );
45	    }
46	
47	    const metric = metrics.find((m) => m.id === metricId);
48	    const score = metric.score;
49	    const passed = score !== null && score >= min;
50	
51	    thresholdList.push({
52	      metric: metricId,
53	      min,
54	      score,
55	      passed
56	    });
57	  }
58	
59	  return thresholdList;
60	}
61	
62	export function loadDataset({ outputsPath, referencesPath, fs: fsModule = defaultFs } = {}) {
63	  if (!outputsPath) {
64	    throw new Error('outputsPath is required for evaluation.');
65	  }
66	
67	  const outputsAbsolute = path.resolve(outputsPath);
68	  const outputsRaw = fsModule.readFileSync(outputsAbsolute, 'utf8');
69	  const outputs = JSON.parse(outputsRaw);
70	
71	  let references = [];
72	  let referencesAbsolute = null;
73	  if (referencesPath) {
74	    referencesAbsolute = path.resolve(referencesPath);
75	    const referencesRaw = fsModule.readFileSync(referencesAbsolute, 'utf8');
76	    references = JSON.parse(referencesRaw);
77	  }
78	
79	  return {
80	    outputs,
81	    references,
82	    outputsPath: outputsAbsolute,
83	    referencesPath: referencesAbsolute
84	  };
85	}
86	
87	export function runEvaluations({
88	  outputs,
89	  references,
90	  metrics = DEFAULT_METRICS
91	} = {}) {
92	  const outs = ensureArray(outputs);
93	  const refs = ensureArray(references);
94	
95	  const evaluations = metrics.map((metric) => {
96	    if (typeof metric === 'function') {
97	      return metric(outs, refs);
98	    }
99	    if (metric && typeof metric.evaluate === 'function') {
100	      return metric.evaluate(outs, refs);
101	    }
102	    throw new Error('Invalid metric supplied to runEvaluations.');
103	  });
104	
105	  return evaluations;
106	}
107	
108	export function generateReport({
109	  evaluations,
110	  outputsPath,
111	  referencesPath,
112	  generatedAt = new Date().toISOString(),
113	  thresholds = {}
114	}) {
115	  const totalSamples = evaluations.reduce((total, metric) => {
116	    if (typeof metric.total === 'number') return Math.max(total, metric.total);
117	    return total;
118	  }, 0);
119	
120	  const thresholdList = evaluateThresholds(evaluations, thresholds);
121	  const passed = thresholdList.length === 0 || thresholdList.every((t) => t.passed);
122	
123	  const report = {
124	    metadata: {
125	      generatedAt,
126	      outputsPath,
127	      referencesPath,
128	      totalSamples
129	    },
130	    metrics: evaluations
131	  };
132	
133	  if (thresholdList.length > 0) {
134	    report.passed = passed;
135	    report.thresholds = thresholdList;
136	  }
137	
138	  return report;
139	}
140	
141	export function writeReport({
142	  report,
143	  format = 'json',
144	  reportPath,
145	  fs: fsModule = defaultFs
146	}) {
147	  const resolved = resolveReportPath(reportPath, format);
148	  const payload = format === 'markdown' ? toMarkdown(report) : toJson(report);
149	  fsModule.writeFileSync(resolved, payload, 'utf8');
150	  return resolved;
151	}
152	
153	export {
154	  DEFAULT_METRICS,
155	  exactMatchMetric,
156	  toxicityMetric,
157	  lengthVarianceMetric
158	};
159	
160	export default {
161	  loadDataset,
162	  runEvaluations,
163	  generateReport,
164	  writeReport,
165	  parseThresholds,
166	  evaluateThresholds,
167	  DEFAULT_METRICS,
168	  exactMatchMetric,
169	  toxicityMetric,
170	  lengthVarianceMetric
171	};
