    expect(result).toHaveLength(1);
    expect(result[0]).toEqual({
      metric: 'exact_match',
      min: 0.5,
      score: 1,
      passed: true
    });
  });

  it('evaluates failing thresholds', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    const result = evaluateThresholds(evaluations, { exact_match: 0.99 });
    expect(result).toHaveLength(1);
    expect(result[0]).toEqual({
      metric: 'exact_match',
      min: 0.99,
      score: 1,
      passed: true
    });
  });

  it('fails threshold when metric has no score', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: []
    });
    const result = evaluateThresholds(evaluations, { exact_match: 0.5 });
    expect(result[0].passed).toBe(false);
    expect(result[0].score).toBe(null);
  });

  it('throws on unknown metric in threshold', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    expect(() => evaluateThresholds(evaluations, { unknown_metric: 0.5 })).toThrow('Unknown metric');
  });

  it('includes thresholds in generated report', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      generatedAt: '2024-01-01T00:00:00.000Z',
      thresholds: { exact_match: 0.5 }
    });
    expect(report.passed).toBe(true);
    expect(report.thresholds).toHaveLength(1);
    expect(report.thresholds[0]).toEqual({
      metric: 'exact_match',
      min: 0.5,
      score: 1,
      passed: true
    });
  });

  it('marks report as failed when threshold fails', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'World'],
      references: ['Hello', 'Goodbye']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      generatedAt: '2024-01-01T00:00:00.000Z',
      thresholds: { exact_match: 0.99 }
    });
    expect(report.passed).toBe(false);
  });

  it('does not include thresholds when none are specified', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json'
    });
    expect(report.passed).toBeUndefined();
    expect(report.thresholds).toBeUndefined();
